<?php
declare(strict_types=1);
require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/library-records.php';
header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
$admin=!empty($is_member)&&($is_admin??'')==='super';$trash=$admin&&($_GET['view']??'')==='trash';$selected=$_GET['id']??'';$query=$_GET['q']??'';
if(!is_string($selected)||($selected!==''&&!preg_match('/^[a-f0-9]{64}$/D',$selected))||!is_string($query)||strlen($query)>1000){http_response_code(400);exit('잘못된 조회 조건입니다.');}
if($admin&&empty($_SESSION['noa_catalog_csrf']))$_SESSION['noa_catalog_csrf']=bin2hex(random_bytes(32));
try{$db=noa_bridge_pdo();$entities=ncl_records($db,$admin,(string)($member['mb_id']??''),$trash);}catch(Throwable $e){error_log('[noa-catalog] '.get_class($e));http_response_code(503);exit('라이브러리를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.');}
$tracks=[];$linkedVideos=[];
$detail=$selected!==''?($entities[$selected]??null):null;if($selected!==''&&!$detail){http_response_code(404);exit('곡을 찾을 수 없거나 열람 권한이 없습니다.');}
if($detail){$batch=$db->query("SELECT batch_id FROM noa_catalog_batches WHERE status='applied' ORDER BY applied_at DESC,batch_id DESC LIMIT 1")->fetchColumn();if($batch&&empty($detail['members'])){$q=$db->prepare('SELECT t.* FROM noa_catalog_tracks t WHERE t.batch_id=? AND t.playlist_id=? ORDER BY t.variant_id,t.position');$q->execute([$batch,$selected]);$tracks=$q->fetchAll(PDO::FETCH_ASSOC);}
 require_once __DIR__.'/noa-bridge/youtube-store.php';$linkedVideos=ny_song_links($db,$selected,$admin);}
function nche(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$rows=array_values(array_map(static function($r)use($admin){unset($r['fields'],$r['members']);if(!$admin)unset($r['selector'],$r['revision']);return $r;},$detail?[$detail]:$entities));
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>통합 라이브러리 | NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css"><script src="/noa-brand.js" defer></script><script src="/noa-ui.js" defer></script><script src="/noa-browse.js" defer></script><script src="/noa-catalog.js?v=<?=hash_file('sha256',__DIR__.'/noa-catalog.js')?>" defer></script><?php if($admin):?><meta name="noa-catalog-csrf" content="<?=nche($_SESSION['noa_catalog_csrf'])?>"><script src="/noa-browse-edit.js?v=<?=hash_file('sha256',__DIR__.'/noa-browse-edit.js')?>" defer></script><?php endif;?></head><body class="noa-page"><main id="catalog-main" data-admin="<?=$admin?'true':'false'?>" data-trash="<?=$trash?'true':'false'?>" data-detail="<?=$detail?'true':'false'?>"><p class="noa-eyebrow">NOA STUDIO / MUSIC LIBRARY</p><h1><?=$trash?'곡 휴지통':'통합 라이브러리'?></h1><p class="noa-muted"><?=$trash?'삭제한 곡은 복원할 수 있습니다. 원본 음원과 변경 이력은 보존됩니다.':'음원·영상과 같은 분류와 곡정보를 사용합니다.'?></p><nav class="catalog-toolbar" aria-label="라이브러리 메뉴"><a href="/noa-catalog.php">전체 라이브러리</a><a href="/noa-music.php">음원</a><a href="/noa-youtube.php">YouTube</a><?php if($admin):?><a href="/noa-library.php">최고관리자 작업실</a><a href="/noa-editor.php">새 곡 등록</a><a href="/noa-catalog.php?view=trash">휴지통</a><?php endif;?></nav><p id="catalog-status" role="status"></p>
<?php if(!$detail):?><label>제목·카테고리·장르·EP 검색<input id="catalog-search" type="search" value="<?=nche($query)?>" placeholder="제목·장르·EP를 입력하세요"></label><section id="catalog-browse" class="noa-browse" aria-label="통합 음악 탐색"></section><p id="catalog-count" class="noa-muted"></p><?php endif;?>
<section id="catalog-items" class="catalog-results" aria-label="곡 목록">
<?php foreach($detail?[$detail]:$entities as $r):$f=$r['fields'];?><article class="song catalog-record" data-key="<?=nche($r['key'])?>" data-browse-key="<?=nche($r['id'])?>"><nav data-record-path="<?=nche($r['id'])?>"></nav><h2><a href="?<?=nche(http_build_query(['id'=>$r['id']]+($trash?['view'=>'trash']:[])))?>"><?=nche($r['title'])?></a></h2>
<?php if($admin&&$r['selector']&&$r['kind']!=='playlist'):?><button type="button" class="noa-button catalog-delete" data-record-action="<?=$trash?'restore':'trash'?>" data-record-id="<?=nche($r['id'])?>"><?=$trash?'복원':'삭제'?></button><?php endif;?>
<?php if($admin&&$r['ambiguous']):?><p class="noa-muted">원본 연결이 여러 개입니다. <a href="/noa-catalog-admin.php">데이터 검토</a>에서 연결을 확인하세요.</p><?php endif;?>
<?php if($detail):?>
<div class="catalog-toolbar"><?php foreach(['youtubeUrl'=>'YouTube 원본','sunoShareUrl'=>'Suno 원본','sunoUrl'=>'Suno 원본','mvUrl'=>'MV 원본'] as $field=>$label):$link=$f[$field]??'';if(!is_string($link)||!filter_var($link,FILTER_VALIDATE_URL)||parse_url($link,PHP_URL_SCHEME)!=='https')continue;if($field==='sunoUrl'&&!empty($f['sunoShareUrl']))continue;?><a href="<?=nche($link)?>" target="_blank" rel="noopener noreferrer"><?=nche($label)?></a><?php endforeach;?></div>
<?php foreach($linkedVideos as $video):if($video['id']===ny_video_id((string)($f['youtubeUrl']??'')))continue;?><a href="https://www.youtube.com/watch?v=<?=nche($video['id'])?>" target="_blank" rel="noopener noreferrer">연결된 YouTube 영상</a><?php endforeach;?>
<?php if(!empty($r['thumb'])&&filter_var($r['thumb'],FILTER_VALIDATE_URL)&&parse_url($r['thumb'],PHP_URL_SCHEME)==='https'):?><img class="catalog-thumb" src="<?=nche($r['thumb'])?>" alt="곡 썸네일" loading="lazy"><?php endif;?>
<?php if(!empty($f['songDescription']??$f['summary']??'')):?><p class="catalog-text"><?=nche((string)($f['songDescription']??$f['summary']))?></p><?php endif;?>
<?php if(!empty($f['description'])):?><details><summary>출처 영상의 원문 설명</summary><p class="catalog-text"><?=nche((string)$f['description'])?></p></details><?php endif;?>
<details open><summary>가사</summary><pre class="catalog-text"><?=nche(noa_sound_lyrics((string)($f['lyricsBlock']??''))?:'등록된 가사가 없습니다.')?></pre></details>
<?php if(!empty($r['members'])):?><h3>수록곡 · 저장된 순서</h3><ol><?php foreach($r['members'] as $m):?><li><?=nche((string)($m['title']??$m['key']??''))?></li><?php endforeach;?></ol><?php endif;?>
<?php if($tracks):?><h3>수록곡 · 원본 재생 순서</h3><ol><?php $variant='';foreach($tracks as $t):$raw=json_decode($t['raw_json'],true);if($variant!==$t['variant_id']){$variant=$t['variant_id'];echo '<li class="noa-muted">목록 버전 '.nche(substr($variant,0,12)).'</li>';}?><li value="<?=(int)$t['position']?>"><?php if(isset($entities[$t['song_id']??''])):?><a href="?id=<?=nche($t['song_id'])?>"><?=nche($entities[$t['song_id']]['title'])?></a><?php else:?><?=nche((string)($raw['title']??$raw['raw']??'곡 식별 검토 중'))?><?php endif;?></li><?php endforeach;?></ol><?php endif;?>
<?php endif;?></article><?php endforeach;?>
</section><?php if(!$entities):?><p class="noa-empty"><?=$trash?'휴지통이 비어 있습니다.':'등록된 곡이 없습니다.'?></p><?php endif;?>
<script type="application/json" id="catalog-records"><?=json_encode($rows,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?></script></main></body></html>
